		private void DoubleAI_Enemy_Seq_027() {
			PRINTF("DoubleAI_Enemy シーケンス027 あばれる、はなびらのまい、げきりんのチェック…\n");
			var waza = CurrentWazaNo();
			var type1 = Call(CMD_CHECK_TYPE, new long[] { CHECK_DEFENCE_FRIEND_TYPE1 });
			var type2 = Call(CMD_CHECK_TYPE, new long[] { CHECK_DEFENCE_FRIEND_TYPE2 });

			if (waza == WazaNo.ABARERU)
			{
				if (type1 == POKETYPE_GHOST || type2 == POKETYPE_GHOST)
				{
					PRINTF("相手の味方にゴーストがいるので230ランダムマイナス\n");
					if (Call(CMD_IF_RND_UNDER, new long[] { 230 }) != 0)
						ScoreCtrl(-4);
					return;
				}
				if (type1 != POKETYPE_IWA && type2 != POKETYPE_IWA &&
					type1 != POKETYPE_HAGANE && type2 != POKETYPE_HAGANE)
					return;
			}
			else if (waza == WazaNo.HANABIRANOMAI)
			{
				if (type1 == POKETYPE_IWA || type2 == POKETYPE_IWA ||
					type1 == POKETYPE_JIMEN || type2 == POKETYPE_JIMEN ||
					type1 == POKETYPE_MIZU || type2 == POKETYPE_MIZU)
					return;
				if (type1 != POKETYPE_HAGANE && type2 != POKETYPE_HAGANE &&
					type1 != POKETYPE_DRAGON && type2 != POKETYPE_DRAGON &&
					type1 != POKETYPE_MUSHI && type2 != POKETYPE_MUSHI &&
					type1 != POKETYPE_HIKOU && type2 != POKETYPE_HIKOU &&
					type1 != POKETYPE_DOKU && type2 != POKETYPE_DOKU &&
					type1 != POKETYPE_HONOO && type2 != POKETYPE_HONOO &&
					type1 != POKETYPE_KUSA && type2 != POKETYPE_KUSA)
					return;
			}
			else if (waza == WazaNo.GEKIRIN)
			{
				if (type1 == POKETYPE_DRAGON || type2 == POKETYPE_DRAGON)
					return;
				if (type1 != POKETYPE_HAGANE && type2 != POKETYPE_HAGANE)
					return;
			}
			else
			{
				return;
			}

			PRINTF("相手の味方に効果いまひとつがいるので200ランダムマイナス\n");
			if (Call(CMD_IF_RND_UNDER, new long[] { 200 }) != 0)
				ScoreCtrl(-2);
		}
