		private void DoubleAI_Enemy_Seq_111() {
			PRINTF("DoubleAI_Enemy シーケンス111 まもるのチェック…\n");
			if (Call(CMD_IF_HP_EQUAL, new long[] { CHECK_ATTACK_FRIEND, 0 }) != 0)
			{
				PRINTF("味方が死んでいるので処理せずリターン\n");
				return;
			}
			var lastWaza = (WazaNo)Call(CMD_CHECK_LAST_WAZA, new long[] { CHECK_ATTACK });
			var tokuseiSelf = Call(CMD_CHECK_TOKUSEI, new long[] { CHECK_ATTACK });
			var tokuseiFriend = Call(CMD_CHECK_TOKUSEI, new long[] { CHECK_ATTACK_FRIEND });
			// the user protected last turn: the ally's spread move bonus does not apply
			var protectedLastTurn = lastWaza == WazaNo.MAMORU || lastWaza == WazaNo.MIKIRI || lastWaza == WazaNo.WAIDOGAADO ||
				lastWaza == WazaNo.FASUTOGAADO || lastWaza == WazaNo.TATAMIGAESI || lastWaza == WazaNo.KINGUSIIRUDO ||
				lastWaza == WazaNo.NIIDORUGAADO;
			var friendKatayaburi = tokuseiFriend == (long)TokuseiNo.KATAYABURI || tokuseiFriend == (long)TokuseiNo.TAABOBUREIZU ||
				tokuseiFriend == (long)TokuseiNo.TERABORUTEEZI;
			string message;

			if (Call(CMD_IF_HAVE_WAZA, new long[] { CHECK_ATTACK_FRIEND, (long)WazaNo.ZIBAKU }) != 0 ||
				Call(CMD_IF_HAVE_WAZA, new long[] { CHECK_ATTACK_FRIEND, (long)WazaNo.DAIBAKUHATU }) != 0)
			{
				if (Call(CMD_CHECK_TYPE, new long[] { CHECK_DEFENCE_TYPE1 }) == POKETYPE_GHOST ||
					Call(CMD_CHECK_TYPE, new long[] { CHECK_DEFENCE_TYPE2 }) == POKETYPE_GHOST ||
					Call(CMD_CHECK_TYPE, new long[] { CHECK_DEFENCE_FRIEND_TYPE1 }) == POKETYPE_GHOST ||
					Call(CMD_CHECK_TYPE, new long[] { CHECK_DEFENCE_FRIEND_TYPE2 }) == POKETYPE_GHOST)
