				if (Call(CMD_CHECK_TOKUSEI, new long[] { CHECK_DEFENCE }) == (long)TokuseiNo.SIMERIKE ||
					Call(CMD_CHECK_TOKUSEI, new long[] { CHECK_DEFENCE_FRIEND }) == (long)TokuseiNo.SIMERIKE ||
					Call(CMD_CHECK_TOKUSEI, new long[] { CHECK_ATTACK_FRIEND }) == (long)TokuseiNo.SIMERIKE)
					return;
				if (protectedLastTurn)
					return;
				PRINTF("味方がじばくを持っていて相手にゴーストがいないので連動ランダム100プラス\n");
				if (Call(CMD_IF_COMMONRND_OVER, new long[] { 160 }) != 0)
					ScoreCtrl(3);
