					ScoreCtrl(-1);
				return;
			}

			if (Call(CMD_IF_HAVE_WAZA, new long[] { CHECK_ATTACK_FRIEND, (long)WazaNo.ZISIN }) != 0 ||
				Call(CMD_IF_HAVE_WAZA, new long[] { CHECK_ATTACK_FRIEND, (long)WazaNo.ZINARASI }) != 0)
