				{
					if (!friendKatayaburi)
						return;
				}
				message = "味方がはなふぶきを持っているので連動100ランダムプラス\n";
			}
			else if (Call(CMD_IF_HAVE_WAZA, new long[] { CHECK_ATTACK_FRIEND, (long)WazaNo.HEDOROWHEEBU }) != 0)
			{
				if (protectedLastTurn)
					return;
				if (tokuseiSelf == (long)TokuseiNo.TEREPASII)
				{
					if (!friendKatayaburi)
						return;
				}
				message = "味方がヘドロウェーブを持っているので連動100ランダムプラス\n";
			}
			else if (Call(CMD_IF_HAVE_WAZA, new long[] { CHECK_ATTACK_FRIEND, (long)WazaNo.BAKUONPA }) != 0)
			{
				if (protectedLastTurn)
					return;
				if (tokuseiSelf == (long)TokuseiNo.TEREPASII)
				{
					if (!friendKatayaburi)
						return;
				}
				message = "味方がばくおんぱを持っているので連動100ランダムプラス\n";
			}
			else
			{
				if (Call(CMD_IF_HAVE_WAZA, new long[] { CHECK_ATTACK_FRIEND, (long)WazaNo.IBARU }) == 0)
					return;
				if (Call(CMD_IF_SIDEEFF, new long[] { CHECK_ATTACK, BTL_SIDEEFF_SINPINOMAMORI }) == 0 &&
					Call(CMD_IF_HAVE_ITEM, new long[] { CHECK_ATTACK, (long)ItemNo.KIINOMI }) == 0 &&
					Call(CMD_IF_HAVE_ITEM, new long[] { CHECK_ATTACK, (long)ItemNo.RAMUNOMI }) == 0 &&
					Call(CMD_CHECK_TOKUSEI, new long[] { CHECK_ATTACK }) != (long)TokuseiNo.MAIPEESU)
					return;
				if (Call(CMD_IF_DMG_PHYSIC_OVER, new long[] { CHECK_ATTACK }) == 0)
					return;
				if (Call(CMD_IF_HP_OVER, new long[] { CHECK_ATTACK_FRIEND, 70 }) == 0)
					return;
				PRINTF("味方がいばるを持っていて条件があっているので連動100マイナス\n");
				if (Call(CMD_IF_COMMONRND_UNDER, new long[] { 100 }) != 0)
					ScoreCtrl(-2);
				return;
			}

			PRINTF(message);
			if (Call(CMD_IF_COMMONRND_OVER, new long[] { 160 }) != 0)
				ScoreCtrl(3);
		}
		private void DoubleAI_Enemy_Seq_147() {
			PRINTF("DoubleAI_Enemy シーケンス147 じしんのチェック…\n");
			if (Call(CMD_IF_HP_EQUAL, new long[] { CHECK_ATTACK_FRIEND, 0 }) != 0)
			{
				PRINTF("味方が死んでいるので計算せずにリターン\n");
				return;
			}
			var friendType1 = Call(CMD_CHECK_TYPE, new long[] { CHECK_ATTACK_FRIEND_TYPE1 });
			var friendType2 = Call(CMD_CHECK_TYPE, new long[] { CHECK_ATTACK_FRIEND_TYPE2 });
			var tokuseiFriend = Call(CMD_CHECK_TOKUSEI, new long[] { CHECK_ATTACK_FRIEND });

			if (Call(CMD_CHECK_WAZA_AISYOU, new long[] { CHECK_ATTACK, CHECK_DEFENCE, (ushort)CurrentWazaNo(), AISYOU_0BAI }) != 0 ||
				Call(CMD_CHECK_WAZA_AISYOU, new long[] { CHECK_ATTACK, CHECK_DEFENCE, (ushort)CurrentWazaNo(), AISYOU_1_4BAI }) != 0 ||
				Call(CMD_CHECK_WAZA_AISYOU, new long[] { CHECK_ATTACK, CHECK_DEFENCE, (ushort)CurrentWazaNo(), AISYOU_1_2BAI }) != 0)
			{
				var friendNotFlying = Call(CMD_IFN_WAZASICK, new long[] { CHECK_ATTACK_FRIEND, WAZASICK_FLYING });
				if (tokuseiFriend == (long)TokuseiNo.TEREPASII || tokuseiFriend == (long)TokuseiNo.HUYUU ||
					friendType2 == POKETYPE_HIKOU || friendType1 == POKETYPE_HIKOU || friendNotFlying == 0)
					return;
				if (friendType1 == POKETYPE_IWA || friendType2 == POKETYPE_IWA || friendType1 == POKETYPE_HONOO || friendType2 == POKETYPE_HONOO ||
					friendType1 == POKETYPE_DOKU || friendType2 == POKETYPE_DOKU || friendType1 == POKETYPE_HAGANE || friendType2 == POKETYPE_HAGANE ||
					friendType1 == POKETYPE_DENKI || friendType2 == POKETYPE_DENKI)
				{
					PRINTF("味方が効果ばつぐんのタイプを持っているのでマイナス\n");
					ScoreCtrl(-3);
					if (Call(CMD_IF_RND_UNDER, new long[] { 200 }) != 0)
						ScoreCtrl(-5);
				}
				return;
			}

			var friendFlying = Call(CMD_IF_WAZASICK, new long[] { CHECK_ATTACK_FRIEND, WAZASICK_FLYING });
			if (friendType2 == POKETYPE_HIKOU || friendType1 == POKETYPE_HIKOU || friendFlying != 0)
			{
				if (Call(CMD_FLDEFF_CHECK, new long[] { EFF_JURYOKU }) != 0)
				{
					PRINTF("味方がひこうふゆうだけど、じゅうりょく中\n");
				}
				else
				{
					PRINTF("味方がひこうふゆうなのでランダム160プラス\n");
					if (Call(CMD_IF_RND_OVER, new long[] { 160 }) != 0)
						ScoreCtrl(3);
					return;
				}
			}

			if (Call(CMD_CHECK_TOKUSEI, new long[] { CHECK_ATTACK_FRIEND }) == (long)TokuseiNo.HUYUU ||
				Call(CMD_CHECK_TOKUSEI, new long[] { CHECK_ATTACK_FRIEND }) == (long)TokuseiNo.TEREPASII)
			{
				var tokuseiSelf = Call(CMD_CHECK_TOKUSEI, new long[] { CHECK_ATTACK });
				if (tokuseiSelf != (long)TokuseiNo.KATAYABURI && tokuseiSelf != (long)TokuseiNo.TAABOBUREIZU && tokuseiSelf != (long)TokuseiNo.TERABORUTEEZI)
				{
					PRINTF("味方がふゆうテレパシーなのでランダム160プラス\n");
					if (Call(CMD_IF_RND_UNDER, new long[] { 160 }) != 0)
						ScoreCtrl(3);
					return;
				}
			}

			if (Call(CMD_IF_HAVE_WAZA, new long[] { CHECK_ATTACK_FRIEND, (long)WazaNo.MAMORU }) != 0 ||
				Call(CMD_IF_HAVE_WAZA, new long[] { CHECK_ATTACK_FRIEND, (long)WazaNo.MIKIRI }) != 0 ||
				Call(CMD_IF_HAVE_WAZA, new long[] { CHECK_ATTACK_FRIEND, (long)WazaNo.KINGUSIIRUDO }) != 0 ||
				Call(CMD_IF_HAVE_WAZA, new long[] { CHECK_ATTACK_FRIEND, (long)WazaNo.NIIDORUGAADO }) != 0 ||
				Call(CMD_IF_HAVE_WAZA, new long[] { CHECK_ATTACK_FRIEND, (long)WazaNo.TATAMIGAESI }) != 0 ||
				Call(CMD_IF_HAVE_WAZA, new long[] { CHECK_ATTACK_FRIEND, (long)WazaNo.WAIDOGAADO }) != 0)
			{
				var lastWaza = (WazaNo)Call(CMD_CHECK_LAST_WAZA, new long[] { CHECK_ATTACK_FRIEND });
				if (lastWaza != WazaNo.MAMORU && lastWaza != WazaNo.MIKIRI && lastWaza != WazaNo.WAIDOGAADO &&
					lastWaza != WazaNo.FASUTOGAADO && lastWaza != WazaNo.TATAMIGAESI && lastWaza != WazaNo.KINGUSIIRUDO &&
					lastWaza != WazaNo.NIIDORUGAADO)
				{
					PRINTF("味方にも攻撃がいくが、まもるを持っているので連動100ランダムプラス\n");
					if (Call(CMD_IF_COMMONRND_OVER, new long[] { 160 }) != 0)
					{
						ScoreCtrl(2);
						return;
					}
				}
			}

			if (friendType1 == POKETYPE_IWA || friendType2 == POKETYPE_IWA || friendType1 == POKETYPE_HONOO || friendType2 == POKETYPE_HONOO ||
				friendType1 == POKETYPE_DOKU || friendType2 == POKETYPE_DOKU || friendType1 == POKETYPE_HAGANE || friendType2 == POKETYPE_HAGANE ||
				friendType1 == POKETYPE_DENKI || friendType2 == POKETYPE_DENKI)
			{
				PRINTF("味方が効果ばつぐんのタイプを持っているのでマイナス\n");
				ScoreCtrl(-3);
				if (Call(CMD_IF_RND_UNDER, new long[] { 200 }) != 0)
					ScoreCtrl(-5);
			}
			if (friendType1 != POKETYPE_KUSA && friendType2 != POKETYPE_KUSA &&
				friendType1 != POKETYPE_MUSHI && friendType2 != POKETYPE_MUSHI)
			{
				PRINTF("味方に技が普通に当たるので180ランダムマイナス\n");
				if (Call(CMD_IF_RND_UNDER, new long[] { 180 }) != 0)
					ScoreCtrl(-1);
				return;
			}
			PRINTF("味方が効果いまひとつのタイプを持っているので連動100ランダムプラス\n");
			if (Call(CMD_IF_COMMONRND_OVER, new long[] { 160 }) != 0)
				ScoreCtrl(2);
		}
		private void DoubleAI_Enemy_Seq_158() {
