				}
			}
			if (mons == (long)MonsNo.BATAHURII || mons == (long)MonsNo.PIKUSII || mons == (long)MonsNo.PARASEKUTO ||
				mons == (long)MonsNo.BAKUHUUN)
			{
				PRINTF("相手がゲッコウガなので220ランダムプラス\n");
				if (Call(CMD_IF_COMMONRND_UNDER, new long[] { 220 }) != 0)
				{
					ScoreCtrl(3);
