		private void DoubleAI_Enemy_Seq_172() {
			PRINTF("DoubleAI_Enemy シーケンス172 このゆびとまれのチェック…\n");
			if (Call(CMD_IF_HP_EQUAL, new long[] { CHECK_ATTACK_FRIEND, 0 }) != 0)
			{
				PRINTF("味方が死んでいるのでマイナス\n");
				ScoreCtrl(-20);
				return;
			}
			if (Call(CMD_IF_HAVE_WAZA_SEQNO, new long[] { CHECK_ATTACK_FRIEND, 172 }) != 0)
			{
				var myMons = Call(CMD_CHECK_MONSNO, new long[] { CHECK_ATTACK });
				var friendMons = Call(CMD_CHECK_MONSNO, new long[] { CHECK_ATTACK_FRIEND });
				long rnd;
				if (friendMons < myMons)
					rnd = Call(CMD_IF_COMMONRND_UNDER, new long[] { 128 });
				else
					rnd = Call(CMD_IF_COMMONRND_OVER, new long[] { 127 });
				if (rnd != 0)
				{
					PRINTF("味方がこのゆびとまれ、いかりのこな持ちなのでマイナス\n");
					ScoreCtrl(-5);
					return;
				}
			}

			long rate;
			if (Call(CMD_IF_HAVE_WAZA, new long[] { CHECK_ATTACK_FRIEND, (long)WazaNo.TORIKKURUUMU }) != 0)
			{
				if (Call(CMD_FLDEFF_CHECK, new long[] { EFF_TRICKROOM }) != 0)
					return;
				PRINTF("味方がトリックルーム持ちなので連動ランダム240プラス\n");
				rate = 240;
			}
			else if (Call(CMD_IF_HAVE_WAZA, new long[] { CHECK_ATTACK_FRIEND, (long)WazaNo.OIKAZE }) != 0)
			{
				if (Call(CMD_IFN_SIDEEFF, new long[] { CHECK_ATTACK, BTL_SIDEEFF_OIKAZE }) == 0)
					return;
				if (Call(CMD_CHECK_AGI_RANK, new long[] { CHECK_ATTACK_FRIEND }) == 0)
					return;
				if (Call(CMD_CHECK_TOKUSEI, new long[] { CHECK_DEFENCE }) == (long)TokuseiNo.ITAZURAGOKORO)
					return;
				PRINTF("味方がおいかぜ持ちなので連動ランダム240プラス\n");
				rate = 240;
			}
			else
			{
				if (Call(CMD_IF_HAVE_WAZA, new long[] { CHECK_ATTACK_FRIEND, (long)WazaNo.HUNKA }) != 0 ||
					Call(CMD_IF_HAVE_WAZA, new long[] { CHECK_ATTACK_FRIEND, (long)WazaNo.SIOHUKI }) != 0)
				{
					if (Call(CMD_CHECK_AGI_RANK, new long[] { CHECK_ATTACK_FRIEND }) == 0)
						return;
					if (Call(CMD_IF_HP_OVER, new long[] { CHECK_ATTACK_FRIEND, 70 }) == 0)
						return;
					PRINTF("味方がふんか、しおふき持ちなので連動ランダム180プラス\n");
				}
				else if (Call(CMD_IF_HAVE_WAZA, new long[] { CHECK_ATTACK_FRIEND, (long)WazaNo.KIAIPANTI }) != 0)
				{
					PRINTF("味方がきあいパンチを持ってるので連動ランダム180プラス\n");
				}
				else if (Call(CMD_IF_HAVE_WAZA, new long[] { CHECK_ATTACK_FRIEND, (long)WazaNo.KARAWOYABURU }) != 0 ||
					Call(CMD_IF_HAVE_WAZA, new long[] { CHECK_ATTACK_FRIEND, (long)WazaNo.RYUUNOMAI }) != 0 ||
					Call(CMD_IF_HAVE_WAZA, new long[] { CHECK_ATTACK_FRIEND, (long)WazaNo.TYOUNOMAI }) != 0 ||
					Call(CMD_IF_HAVE_WAZA, new long[] { CHECK_ATTACK_FRIEND, (long)WazaNo.KOUSOKUIDOU }) != 0 ||
					Call(CMD_IF_HAVE_WAZA, new long[] { CHECK_ATTACK_FRIEND, (long)WazaNo.ROKKUKATTO }) != 0 ||
					Call(CMD_IF_HAVE_WAZA, new long[] { CHECK_ATTACK_FRIEND, (long)WazaNo.BODHIPAAZI }) != 0 ||
					Call(CMD_IF_HAVE_WAZA, new long[] { CHECK_ATTACK_FRIEND, (long)WazaNo.GIATHENZI }) != 0)
				{
					if (Call(CMD_CHECK_AGI_RANK, new long[] { CHECK_ATTACK_FRIEND }) == 0)
						return;
					PRINTF("味方が素早さアップを持ってるので連動ランダム180プラス\n");
				}
				else
				{
					return;
				}
				rate = 180;
			}
			if (Call(CMD_IF_COMMONRND_UNDER, new long[] { rate }) != 0)
				ScoreCtrl(3);
		}
