		private void DoubleAI_Enemy_Seq_259_sub(int value) {
			var myRank = Call(CMD_CHECK_AGI_RANK, new long[] { CHECK_ATTACK });
			var friendRank = Call(CMD_CHECK_AGI_RANK, new long[] { CHECK_ATTACK_FRIEND });
			if (Call(CMD_IF_HAVE_WAZA, new long[] { CHECK_ATTACK_FRIEND, (long)WazaNo.TORIKKURUUMU }) != 0)
			{
				if (myRank == 3)
				{
					if (Call(CMD_IF_COMMONRND_UNDER, new long[] { 150 }) == 0)
						value = -5;
				}
				else if (friendRank == myRank)
				{
					var myMons = Call(CMD_CHECK_MONSNO, new long[] { CHECK_ATTACK });
					var friendMons = Call(CMD_CHECK_MONSNO, new long[] { CHECK_ATTACK_FRIEND });
					var rnd = Call(CMD_IF_COMMONRND_UNDER, new long[] { 128 });
					if (myMons <= friendMons)
					{
						if (rnd == 0)
							value = -5;
					}
					else
					{
						if (rnd != 0)
							value = -5;
					}
				}
				else
				{
					if (Call(CMD_IF_COMMONRND_UNDER, new long[] { 150 }) != 0)
						value = -5;
				}
			}
			ScoreCtrl(value);
		}
