			var friendType2 = Call(CMD_CHECK_TYPE, new long[] { CHECK_ATTACK_FRIEND_TYPE2 });
			var defType1 = Call(CMD_CHECK_TYPE, new long[] { CHECK_DEFENCE_TYPE1 });
			var defType2 = Call(CMD_CHECK_TYPE, new long[] { CHECK_DEFENCE_TYPE2 });
			var defFriendType1 = Call(CMD_CHECK_TYPE, new long[] { CHECK_DEFENCE_FRIEND_TYPE1 });
			var defFriendType2 = Call(CMD_CHECK_TYPE, new long[] { CHECK_DEFENCE_FRIEND_TYPE2 });
			PRINTF(string.Format("自分のタイプ1 = {0},　味方のタイプ1 ={1}, 敵のタイプ1　={2},敵仲間のタイプ1　= {3}\n", myType1, friendType1, defType1, defFriendType1));
			PRINTF(string.Format("自分のタイプ2 = {0},　味方のタイプ2 ={1}, 敵のタイプ2　={2},敵仲間のタイプ2　= {3}\n", myType2, friendType2, defType2, defFriendType2));

			if (myType1 != POKETYPE_ESPER && myType2 != POKETYPE_ESPER)
				return;

			if ((friendType2 == POKETYPE_KOORI || friendType1 == POKETYPE_KOORI || friendType2 == POKETYPE_HAGANE || friendType1 == POKETYPE_HAGANE ||
				 friendType2 == POKETYPE_AKU || friendType1 == POKETYPE_AKU || friendType2 == POKETYPE_IWA || friendType1 == POKETYPE_IWA ||
				 friendType1 == POKETYPE_NORMAL || friendType2 == POKETYPE_NORMAL) &&
