		private void DoubleAI_Friend_Main() {
			if (Call(CMD_IF_HP_EQUAL, new long[] { CHECK_ATTACK_FRIEND, 0 }) != 0)
			{
				PRINTF("味方がいないのでマイナス\n");
				ScoreCtrl(-30);
				return;
			}

			switch (Call(CMD_CHECK_WORKWAZA_SEQNO, Array.Empty<long>()))
			{
				case 118:
					DoubleAI_Friend_Seq_118();
					break;
				case 143:
					DoubleAI_Friend_Seq_143();
					break;
				case 154:
					DoubleAI_Friend_Seq_154();
					break;
				case 167:
					DoubleAI_Friend_Seq_167();
					break;
				case 176:
					DoubleAI_Friend_Seq_176();
					break;
				case 178:
					DoubleAI_Friend_Seq_178();
					break;
				case 191:
					DoubleAI_Friend_Seq_191();
					break;
				case 226:
					DoubleAI_Friend_Seq_226();
					break;
				case 285:
					DoubleAI_Friend_Seq_285();
					break;
				case 299:
					DoubleAI_Friend_Seq_299();
					break;
				case 300:
					DoubleAI_Friend_Seq_300();
					break;
				// Byte jump table @03d5a719 (seq 385..393): 386 and 393 share seq 309's tail call (01c0b9a0)
				case 309:
				case 386:
				case 393:
					DoubleAI_Friend_Seq_309();
					break;
				case 362:
					DoubleAI_Friend_Seq_362();
					break;
				case 385:
					DoubleAI_Friend_Seq_385();
					break;
				case 388:
					DoubleAI_Friend_Seq_388();
					break;
				case 391:
					DoubleAI_Friend_Seq_391();
					break;
				case 398:
					DoubleAI_Friend_Seq_398();
					break;
				case 399:
					DoubleAI_Friend_Seq_399();
					break;
				case 402:
					DoubleAI_Friend_Seq_402();
					break;
				case 434:
					DoubleAI_Friend_Seq_434();
					break;
				default:
					PRINTF("味方への攻撃はマイナス\n");
					ScoreCtrl(-20);
					break;
			}
		}
		private void DoubleAI_Friend_Seq_118() {
			PRINTF("DoubleAI_Friend シーケンス118　いばるのチェック…\n");
			if (Call(CMD_IF_DMG_PHYSIC_UNDER, new long[] { CHECK_ATTACK_FRIEND }) != 0)
			{
				PRINTF("味方は特殊型なのでマイナスです\n");
				ScoreCtrl(-12);
				return;
			}
			if (Call(CMD_CHECK_TOKUSEI, new long[] { CHECK_DEFENCE }) == (long)TokuseiNo.AMANOZYAKU)
			{
				PRINTF("味方があまのじゃくなのでマイナスです\n");
				ScoreCtrl(-12);
				return;
			}
			// IF_SIDEEFF is given no effect argument here and its result is compared with an effect ID (shipped script)
			if (Call(CMD_IF_SIDEEFF, new long[] { CHECK_DEFENCE }) == BTL_SIDEEFF_SINPINOMAMORI ||
				Call(CMD_IF_HAVE_ITEM, new long[] { CHECK_ATTACK_FRIEND, (long)ItemNo.KIINOMI }) != 0 ||
				Call(CMD_IF_HAVE_ITEM, new long[] { CHECK_ATTACK_FRIEND, (long)ItemNo.RAMUNOMI }) != 0 ||
				Call(CMD_CHECK_TOKUSEI, new long[] { CHECK_DEFENCE }) == (long)TokuseiNo.MAIPEESU)
			{
				if (Call(CMD_IF_HP_OVER, new long[] { CHECK_ATTACK_FRIEND, 70 }) != 0)
				{
					PRINTF("味方が物理型でしんぴのまもり中かマイペースかキーラム持ちでHP70以上なので連動100プラス\n");
					if (Call(CMD_IF_COMMONRND_UNDER, new long[] { 100 }) != 0)
					{
						ScoreCtrl(2);
						return;
					}
				}
			}
			ScoreCtrl(-10);
		}
