			var monsFriend = Call(CMD_CHECK_MONSNO, new long[] { CHECK_ATTACK_FRIEND });
			long rate;
			switch (tokuseiSelf)
			{
				case (long)TokuseiNo.TIKUDEN:
				case (long)TokuseiNo.TYOSUI:
				case (long)TokuseiNo.MAIPEESU:
				case (long)TokuseiNo.HUYUU:
				case (long)TokuseiNo.HIRAISIN:
				case (long)TokuseiNo.SUISUI:
				case (long)TokuseiNo.YOURYOKUSO:
				case (long)TokuseiNo.ATUISIBOU:
				case (long)TokuseiNo.HARIKIRI:
				case (long)TokuseiNo.MEROMEROBODHI:
				case (long)TokuseiNo.PURASU:
				case (long)TokuseiNo.MAINASU:
				case (long)TokuseiNo.KARUWAZA:
				case (long)TokuseiNo.TETUNOKOBUSI:
				case (long)TokuseiNo.SUNAIPAA:
				case (long)TokuseiNo.TEKUNISYAN:
				case (long)TokuseiNo.BUKIYOU:
				case (long)TokuseiNo.KATAYABURI:
				case (long)TokuseiNo.AISUBODHI:
				case (long)TokuseiNo.MURAKKE:
				case (long)TokuseiNo.ZISINKAZYOU:
					if (Call(CMD_CHECK_NEKODAMASI, new long[] { CHECK_ATTACK }) != 0)
						return;
					PRINTF("なかまづくりの技を持っていて登場ターンなので連動180ランダムプラス\n");
					rate = 180;
					break;
				case (long)TokuseiNo.DENKIENZIN:
					if (monsFriend != (long)MonsNo.GYARADOSU && monsFriend != (long)MonsNo.PERIPPAA && monsFriend != (long)MonsNo.MANTAIN)
						return;
					PRINTF("自分がひらいしん、ちくでん、デンキエンジンで味方が電気４倍なので連動128ランダムプラス\n");
					rate = 128;
					break;
				case (long)TokuseiNo.URUOIBODHI:
					if (Call(CMD_IF_POKESICK, new long[] { CHECK_ATTACK_FRIEND }) == 0)
						return;
					if (Call(CMD_CHECK_WEATHER, Array.Empty<long>()) != WEATHER_AME)
						return;
					PRINTF("自分がうるおいボディで味方が状態異常で天気が雨なので連動128ランダムプラス\n");
					if (Call(CMD_IF_COMMONRND_UNDER, new long[] { 128 }) != 0)
						ScoreCtrl(1);
					return;
				case (long)TokuseiNo.SOUSYOKU:
					if (monsFriend != (long)MonsNo.OMUSUTAA && monsFriend != (long)MonsNo.KABUTOPUSU && monsFriend != (long)MonsNo.NUOO &&
						monsFriend != (long)MonsNo.GOROONYA &&
						monsFriend != (long)MonsNo.RAGURAAZI && monsFriend != (long)MonsNo.NAMAZUN &&
						monsFriend != (long)MonsNo.ZIIRANSU && monsFriend != (long)MonsNo.DOSAIDON && monsFriend != (long)MonsNo.TORITODON)
						return;
					PRINTF("自分がそうしょくで味方が草４倍なので連動230ランダムプラス\n");
					rate = 230;
					break;
				case (long)TokuseiNo.MEGARANTYAA:
					if (Call(CMD_IF_HAVE_WAZA, new long[] { CHECK_ATTACK_FRIEND, (long)WazaNo.AKUNOHADOU }) == 0 &&
						Call(CMD_IF_HAVE_WAZA, new long[] { CHECK_ATTACK_FRIEND, (long)WazaNo.HADOUDAN }) == 0 &&
						Call(CMD_IF_HAVE_WAZA, new long[] { CHECK_ATTACK_FRIEND, (long)WazaNo.MIZUNOHADOU }) == 0 &&
						Call(CMD_IF_HAVE_WAZA, new long[] { CHECK_ATTACK_FRIEND, (long)WazaNo.RYUUNOHADOU }) == 0 &&
						Call(CMD_IF_HAVE_WAZA, new long[] { CHECK_ATTACK_FRIEND, (long)WazaNo.IYASINOHADOU }) == 0)
						return;
					PRINTF("自分がメガランチャーで味方がはどう技を持っているので連動200ランダムプラス\n");
					rate = 200;
					break;
				default:
					return;
			}
			if (Call(CMD_IF_COMMONRND_UNDER, new long[] { rate }) != 0)
				ScoreCtrl(2);
		}
